-- Fakt kartochkalari orqa tomonining ruscha matni — 64-partiya:
-- Chingiz Ahmarov (yakuni), Dilshod otin, Durbek, Elbek.

UPDATE fact_cards SET detail_ru = 'Чингиз Ахмаров умер 13 мая 1995 года в Ташкенте. В последние годы жизни (1992–1995) он создал такие работы, как «Амир Темур и Биби-ханым», «Амир Темур и дервиш», «Амир Темур и Баязид». Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква А, с. 865–866.' WHERE id = 2154;

UPDATE fact_cards SET detail_ru = 'Дильшоди Барно родилась в 1800 году в городе Ура-Тюбе. Грамоте она выучилась у своего отца Рахимкула-суфи. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2155;
UPDATE fact_cards SET detail_ru = 'Настоящее имя поэтессы — Дильшод, дочь Рахимкула-суфи. Она была известна под именами Дильшод-отин, Барно и Дильшоди Барно. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2156;
UPDATE fact_cards SET detail_ru = 'Дильшоди Барно держала школу — обучала женщин и девушек грамоте. За это занятие её и знали под именем Дильшод-отин. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2157;
UPDATE fact_cards SET detail_ru = 'Поэтесса Анбар Отин была одной из одарённых учениц Дильшоди Барно. Как и её наставница, она стала одной из известных поэтесс узбекской классической словесности. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2158;
UPDATE fact_cards SET detail_ru = 'Дильшоди Барно писала на узбекском и таджикском языках в жанрах газели, мухаммаса, мусаддаса, загадки и других. Её 91 узбекское и 51 таджикское стихотворение дошли до нас в трёх рукописных списках, и хранятся они в Институте востоковедения Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2159;
UPDATE fact_cards SET detail_ru = 'В сочинении «Тарихи муходжирон» отражены исторические и общественно-политические события в Кокандском ханстве XIX века. В своих сочинениях поэтесса привела также сведения о творчестве более чем тридцати поэтесс, живших в Ура-Тюбе и Коканде; известно и её сочинение «Сабот уль-башар маа тарихи муходжирон». Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2160;
UPDATE fact_cards SET detail_ru = 'В своём творчестве Дильшоди Барно призывала женщин быть просвещёнными, свободными и равноправными членами общества. Её поэзию оценивают как поднявшуюся до уровня художественной летописи народной судьбы. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2161;
UPDATE fact_cards SET detail_ru = 'Дильшоди Барно умерла в 1905/06 году в городе Коканде. Её рукописные сочинения хранятся в Институте востоковедения Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2162;

UPDATE fact_cards SET detail_ru = 'Точный год рождения Дурбека в источниках не сохранился. Он считается узбекским поэтом, жившим в конце XIV — начале XV века. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2163;
UPDATE fact_cards SET detail_ru = 'Жизнь и творчество Дурбека связаны с городом Балхом. В его поэме изображены виды, события и обычаи, свойственные городам и селениям Средней Азии. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2164;
UPDATE fact_cards SET detail_ru = 'Поэма Дурбека «Юсуф и Зулейха» написана в 1409 году и представляет собой стихотворное истолкование на узбекском языке повести, основанной на широко распространённом на Востоке странствующем сюжете. Рукописные списки поэмы хранятся в Институте востоковедения Академии наук Узбекистана, а также в библиотеках Парижа и Стамбула. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2165;
UPDATE fact_cards SET detail_ru = 'Поэму «Юсуф и Зулейха» Дурбек создал на тюркском (староузбекском) языке. В поэме есть его строка о том, что он твёрдо решил писать на тюркском языке. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2166;
UPDATE fact_cards SET detail_ru = 'В поэме с высоким мастерством изображены осада города Балха и тяжкие беды, обрушившиеся на народ. Эти картины внесли в сочинение живые виды тогдашней жизни. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2167;
UPDATE fact_cards SET detail_ru = 'Главный герой поэмы — Юсуф. В сочинении раскрыты его судьба и отношение к жизни в разных обстоятельствах. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2168;
UPDATE fact_cards SET detail_ru = 'Точный год смерти Дурбека в источниках не указан; считается, что он умер в начале XV века. От него до нас дошла только поэма «Юсуф и Зулейха». Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2169;

UPDATE fact_cards SET detail_ru = 'Эльбек (настоящее имя — Машрик Юнусов) родился в 1898 году в селении Хумсан Искандарской волости Ташкентской области, в семье бедного землепашца. Его детские и юношеские годы прошли очень тяжело. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2170;
UPDATE fact_cards SET detail_ru = 'Эльбек начал учение в 1905 году в сельской школе, с 1911 года учился в ташкентской школе «Хоний», с 1914-го — в школе «Намуна» и преподавал там. После 1917 года он учился и на курсах подготовки учителей. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2171;
UPDATE fact_cards SET detail_ru = 'Первый стихотворный сборник Эльбека «Армуган» вышел в 1921 году. Позже были изданы стихотворные сборники «Зеркало», «Отсветы» (1925), «Весна» (1929), а также рассказы «Ойхон» (1920) и «Пахарь Тургун» (1925). В «Пахаре Тургуне» описано тяжёлое положение узбекских землепашцев. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2172;
UPDATE fact_cards SET detail_ru = 'Эльбек создал учебные книги «Образец» (1924), «Прекрасные писатели» (1925), «Знание» (1927), пособие «Родной язык в начальной школе» и сочинение «Словарь и термины» (1924). Эти книги были важными пособиями для узбекских школ. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2173;
UPDATE fact_cards SET detail_ru = 'Эльбек написал такие работы о правописании и законах узбекского языка, как «Перед созывом съезда по правописанию и языку» (1920), «О законах тюркских языков» (1922), «Учебник языка» (1923). В 1919 году он участвовал в «Чигатой гурунги» под началом Фитрата и работал в узбекской научной комиссии. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2174;
UPDATE fact_cards SET detail_ru = 'Эльбек вместе с Чулпаном и Гуламом Зафари собрал в Фергане тысячи народных пословиц и поговорок, песен и лапаров и подготовил сборники «Лапары» (1924), «Сборник песен» и «Детские песни» (1934, 1935). Работал он и над «Словарём узбекского фольклора» и над «Материалами к толковому словарю узбекского народа». Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2175;
UPDATE fact_cards SET detail_ru = 'В 1937 году Эльбек переложил на узбекский «Сказку о рыбаке и рыбке» и «Сказку о попе и работнике его Балде» Пушкина. Он переводил также басни Крылова и стихи Некрасова и написал статью «Народная словесность в творчестве Пушкина и узбекский перевод» (1937). Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2176;
UPDATE fact_cards SET detail_ru = 'В годы сталинских репрессий Эльбек был безвинно обвинён и погиб, как и его современники Фитрат, Чулпан, Абдулла Кадыри и другие; точная дата его смерти в источнике не указана. Позже отдельные его сочинения вновь вошли в учебники и хрестоматии. Источник: Ziyouz.com, статья «Эльбек».' WHERE id = 2177;
